Section CANSEC1. Context {rc : runConstT}.

Section RSA.
  Variable AI : AMallocIface.
  Notation CI := (aci AI).
  Variable rng_fs : alayout -> footprint -> Prop.
  Variable kk : nat.
  Hypothesis FDWK : fse_decomp_stmtA AI rng_fs kk.
  Variables (L : alayout) (RNG : footprint) (ra gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word)
            (FR : bvmap 5 word) (fc : bv 32) (m0 : amem) (st : astate) (LB : list ablock)
            (SPV HW RK NSP TLP S W : Z) (src : list Z) (jh jr jw : list byte) (nsv tlv : word) (lo : Z) (rstk : region).
  Hypothesis AH : AHEAP AI L RNG st LB m0.
  Hypothesis LEK : fake0_lek kk LB.
  Hypothesis LBH : forall b, In b LB -> ablk (ab_addr b) (ab_addr b + ab_size b).
  Hypothesis HWA : u8arr asegs m0 HW jh.
  Hypothesis LJH : zlen jh = 256.
  Hypothesis RKA : u8arr asegs m0 RK jr.
  Hypothesis LJR : zlen jr = 52.
  Hypothesis NSC : rw_cells asegs m0 NSP [C4 nsv].
  Hypothesis TLC : rw_cells asegs m0 TLP [C4 tlv].
  Hypothesis SRC : bytes_at asegs m0 S (map (Z_to_bv 8) src).
  Hypothesis BYS : Forall (fun c => 0 <= c < 256) src.
  Hypothesis NSR : zlen src < 2^26.
  Hypothesis WKA : u8arr asegs m0 W jw.
  Hypothesis LJW : zlen jw = 876.
  Hypothesis SPA : rw_cells asegs m0 SPV [C8 (Z_to_bv 64 876)].
  Hypothesis HHW : hblk8 LB HW 256.
  Hypothesis HRK : hblk8 LB RK 52.
  Hypothesis RK4 : RK mod 4 = 0.
  Hypothesis HWK : hblk8 LB W 876.
  Hypothesis W8 : W mod 8 = 0.
  Hypothesis FNS : fcellA m0 LB NSP 4.
  Hypothesis NS4 : NSP mod 4 = 0.
  Hypothesis FTL : fcellA m0 LB TLP 4.
  Hypothesis TL4 : TLP mod 4 = 0.
  Hypothesis HSB0 : 0 < zlen src -> bufH LB S (zlen src).
  Hypothesis S15 : 15 <= S.
  Hypothesis DHR : HW + 256 <= RK \/ RK + 52 <= HW.
  Hypothesis DHS : HW + 256 <= S \/ S + zlen src <= HW.
  Hypothesis DHW : HW + 256 <= W \/ W + 876 <= HW.
  Hypothesis DRS : RK + 52 <= S \/ S + zlen src <= RK.
  Hypothesis DRW : RK + 52 <= W \/ W + 876 <= RK.
  Hypothesis DSW : S + zlen src <= W \/ W + 876 <= S.
  Hypothesis DNT : NSP + 4 <= TLP \/ TLP + 4 <= NSP.
  Hypothesis ST : stk asegs m0 lo SPV.
  Hypothesis BOT : ATOP + 4096 <= lo.
  Hypothesis LO : lo <= SPV - AHUF_RSTATS_STACK.
  Hypothesis SPT : SPV + 16 < al_top L.
  Hypothesis SP16 : SPV mod 16 = 0.
  Hypothesis RCL : rclean m0 rstk.
  Hypothesis RLO : r_lo rstk <= lo.
  Hypothesis RHI : SPV <= r_hi rstk.
  Hypothesis RRLO : ATOP <= r_rlo rstk.
  Hypothesis MI : mem_inv asegs m0.
  Hypothesis TP : tp = Z_to_bv 64 ATP.
  Hypothesis ZMK : zshadow m0 ABIT_MASK 128.
  Hypothesis MKCI : forall a, ABIT_MASK <= a < ABIT_MASK + 128 -> in_ranges CI a.
  Hypothesis RSTK : rng RNG lo (al_top L - lo).
  Hypothesis RI : rng_aimg RNG.
  Hypothesis RISH : rng_aimg_sh RNG.
  Hypothesis RFS : rng_fs L RNG.
  Hypothesis RRS : rrng RNG rstk.
  Hypothesis RNS : rng RNG NSP 4.
  Hypothesis RNSs : rng RNG (shad NSP) 1.
  Hypothesis RTL : rng RNG TLP 4.
  Hypothesis RTLs : rng RNG (shad TLP) 1.

  Notation SP := (SPV - 64).
  Notation POST := (huf_rstats_postA AI L RNG ra gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 FR fc st LB SPV HW RK NSP TLP W src lo m0).
  Notation PRS := (fun a => aclient_addr CI LB SPV a /\ ~ (HW <= a < HW + 256) /\ ~ (RK <= a < RK + 52)
                            /\ ~ (NSP <= a < NSP + 4) /\ ~ (TLP <= a < TLP + 4) /\ ~ (W <= a < W + 876)).
  Notation FRM := [C8 s6; C8 s5; C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra].

